/// <summary>
/// Data contract class for service <c>METPurchaseOrderReceiptRequestContract</c>
/// </summary>
[DataContractAttribute]
public class METPurchaseOrderReceiptRequestContract
{
    ProductReceiptId    productReceiptId;
    DataAreaId          dataAreaId;
    PurchId             purchId;
    TransDate           productReceiptDate;
    ItemId              itemId;
    InventBatchId       inventBatchId;
    InventQty           receivedQty;
    InventQty           catchWeightQty;
    

}

Method.Source:
/// <summary>
/// Gets/sets the Quantity
/// </summary>
/// <param name = "_receivedQty">Quantity reference</param>
/// <returns>Quantity</returns>
[DataMemberAttribute('Quantity')]
public InventQty parmQuantity(InventQty _receivedQty = receivedQty )
{
    receivedQty  = _receivedQty;
    return receivedQty ;
}

/// <summary>
/// Gets/sets the Catch Weight Quantity
/// </summary>
/// <param name = "_catchWeightQty">Quantity reference</param>
/// <returns>Quantity</returns>
[DataMemberAttribute('Catchweight quantity')]
public InventQty parmCatchWeightQty(InventQty _catchWeightQty = catchWeightQty)
{
    catchWeightQty = _catchWeightQty;
    return catchWeightQty;
}

/// <summary>
/// Gets/sets the Batch Number
/// </summary>
/// <param name = "_inventBatchId">Invent Batch Reference</param>
/// <returns>InvantBatch</returns>
[DataMemberAttribute('Batch number')]
public InventBatchId parmInventBatchId(InventBatchId _inventBatchId = inventBatchId)
{
    inventBatchId = _inventBatchId;
    return inventBatchId;
}

/// <summary>
/// Gets/sets the Item Number
/// </summary>
/// <param name = "_itemId">ItemId reference</param>
/// <returns>ItemId</returns>
[DataMemberAttribute('Item number')]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

/// <summary>
/// Gets/sets the Product Receipt Date
/// </summary>
/// <param name = "_productReceiptDate">Product Receipt Date reference</param>
/// <returns>ProductReceiptDate</returns>
[DataMemberAttribute('Product receipt date')]
public TransDate parmProductReceiptDate(TransDate _productReceiptDate = productReceiptDate)
{
    productReceiptDate = _productReceiptDate;
    return productReceiptDate;
}

/// <summary>
/// Gets/sets the Product Receipt Number
/// </summary>
/// <param name = "_productReceiptId">Product Receipt Number reference</param>
/// <returns>ProductReceiptNumber</returns>
[DataMemberAttribute('Receipt number')]
public ProductReceiptId parmProductReceipt(ProductReceiptId _productReceiptId = productReceiptId)
{
    productReceiptId = _productReceiptId;
    return productReceiptId;
}

/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Gets/sets the purchase order number
/// </summary>
/// <param name = "_purchId">Purchase order number</param>
/// <returns>return the purchase order number</returns>
[DataMemberAttribute('PurchaseOrderNumber')]
public PurchId parmPurchId(PurchId _purchId = purchId)
{
    purchId = _purchId;
    return purchId;
}

/// <summary>
/// Instantiate new object
/// </summary>
/// <returns>The new object</returns>
public static METPurchaseOrderReceiptRequestContract construct()
{
    return new METPurchaseOrderReceiptRequestContract();
}
